/** 获取某时期的所有片段ID列表 */
export function getFragmentsByPeriod(period: 'A' | 'B' | 'C' | 'N'): string[] {
  return Object.keys(FRAGMENT_LINES).filter(id => FRAGMENT_LINES[id].period === period);
}
